CREATE TYPE public.app_role AS ENUM ('admin','moderator','user');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT 'Reader', username text UNIQUE, biography text NOT NULL DEFAULT '', avatar_url text, country text, interests text[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING (true);
CREATE POLICY profiles_edit ON public.profiles FOR UPDATE TO authenticated USING(auth.uid()=id) WITH CHECK(auth.uid()=id);
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL DEFAULT 'user', UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE FUNCTION public.new_reader() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'display_name',NEW.raw_user_meta_data->>'full_name','Reader')); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'user'); RETURN NEW; END $$;
CREATE TRIGGER create_reader AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.new_reader();
CREATE TABLE public.books (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slug text NOT NULL UNIQUE,title text NOT NULL,author text NOT NULL,cover_url text NOT NULL DEFAULT '',genre text NOT NULL DEFAULT 'Fiction',subgenre text NOT NULL DEFAULT '',description text NOT NULL DEFAULT '',synopsis text NOT NULL DEFAULT '',publication_date date,isbn text,purchase_url text,format text NOT NULL DEFAULT 'Paperback',total_pages integer NOT NULL DEFAULT 300 CHECK(total_pages>0),featured boolean NOT NULL DEFAULT false,published boolean NOT NULL DEFAULT true,eligible boolean NOT NULL DEFAULT true,source text NOT NULL DEFAULT 'author',discussion_prompts jsonb NOT NULL DEFAULT '[]',benchmarks jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.books TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.books TO authenticated; GRANT ALL ON public.books TO service_role;
ALTER TABLE public.books ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_books ON public.books FOR SELECT USING(published OR public.has_role(auth.uid(),'admin'));
CREATE POLICY admin_books ON public.books FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.reader_shelves (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,book_id uuid NOT NULL REFERENCES public.books(id) ON DELETE CASCADE,category text NOT NULL DEFAULT 'Want to Read' CHECK(category IN ('Currently Reading','Completed','Next Reads','Want to Read','On Hold','Dropped','Want to Reread','Favorites')),current_page integer NOT NULL DEFAULT 0 CHECK(current_page>=0),total_pages integer NOT NULL DEFAULT 300 CHECK(total_pages>0),started_at date,completed_at date,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,book_id),CHECK(current_page<=total_pages));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.reader_shelves TO authenticated; GRANT ALL ON public.reader_shelves TO service_role;
ALTER TABLE public.reader_shelves ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_shelves ON public.reader_shelves FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.book_ratings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,book_id uuid NOT NULL REFERENCES public.books(id) ON DELETE CASCADE,rating integer NOT NULL CHECK(rating BETWEEN 1 AND 5),UNIQUE(user_id,book_id));
GRANT SELECT ON public.book_ratings TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.book_ratings TO authenticated; GRANT ALL ON public.book_ratings TO service_role;
ALTER TABLE public.book_ratings ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_ratings ON public.book_ratings FOR SELECT USING(true); CREATE POLICY own_ratings ON public.book_ratings FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.good_book_votes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,book_id uuid NOT NULL REFERENCES public.books(id) ON DELETE CASCADE,UNIQUE(user_id,book_id));
GRANT SELECT ON public.good_book_votes TO anon; GRANT SELECT,INSERT,DELETE ON public.good_book_votes TO authenticated; GRANT ALL ON public.good_book_votes TO service_role;
ALTER TABLE public.good_book_votes ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_good_votes ON public.good_book_votes FOR SELECT USING(true); CREATE POLICY own_good_votes ON public.good_book_votes FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.contributions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE,book_id uuid REFERENCES public.books(id) ON DELETE CASCADE,parent_id uuid REFERENCES public.contributions(id) ON DELETE CASCADE,kind text NOT NULL DEFAULT 'discussion' CHECK(kind IN('discussion','review','comment')),title text NOT NULL DEFAULT '',body text NOT NULL CHECK(length(body)>0 AND length(body)<=10000),source text NOT NULL DEFAULT 'reader' CHECK(source IN('reader','editorial')),published boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),CHECK((source='reader' AND user_id IS NOT NULL) OR source='editorial'));
GRANT SELECT ON public.contributions TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.contributions TO authenticated; GRANT ALL ON public.contributions TO service_role;
ALTER TABLE public.contributions ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_contributions ON public.contributions FOR SELECT USING(published OR user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY own_contributions ON public.contributions FOR ALL TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin')) WITH CHECK((user_id=auth.uid() AND source='reader') OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.contribution_likes (user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,contribution_id uuid NOT NULL REFERENCES public.contributions(id) ON DELETE CASCADE,PRIMARY KEY(user_id,contribution_id));
GRANT SELECT ON public.contribution_likes TO anon; GRANT SELECT,INSERT,DELETE ON public.contribution_likes TO authenticated; GRANT ALL ON public.contribution_likes TO service_role;
ALTER TABLE public.contribution_likes ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_likes ON public.contribution_likes FOR SELECT USING(true); CREATE POLICY own_likes ON public.contribution_likes FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.community_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),kind text NOT NULL CHECK(kind IN('challenge','buddy','poll','announcement','botm')),title text NOT NULL,description text NOT NULL DEFAULT '',book_id uuid REFERENCES public.books(id) ON DELETE SET NULL,starts_at date,ends_at date,options jsonb NOT NULL DEFAULT '[]',published boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.community_events TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.community_events TO authenticated; GRANT ALL ON public.community_events TO service_role;
ALTER TABLE public.community_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_events ON public.community_events FOR SELECT USING(published OR public.has_role(auth.uid(),'admin')); CREATE POLICY admin_events ON public.community_events FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.event_participants (user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,event_id uuid NOT NULL REFERENCES public.community_events(id) ON DELETE CASCADE,choice integer,goal integer NOT NULL DEFAULT 12 CHECK(goal>0),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,event_id));
GRANT SELECT ON public.event_participants TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.event_participants TO authenticated; GRANT ALL ON public.event_participants TO service_role;
ALTER TABLE public.event_participants ENABLE ROW LEVEL SECURITY;
CREATE POLICY participant_read ON public.event_participants FOR SELECT USING(true); CREATE POLICY own_participation ON public.event_participants FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.author_submissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,author_name text NOT NULL,email text NOT NULL,country text NOT NULL DEFAULT '',biography text NOT NULL DEFAULT '',title text NOT NULL,genre text NOT NULL,synopsis text NOT NULL,description text NOT NULL DEFAULT '',cover_path text NOT NULL DEFAULT '',manuscript_path text NOT NULL DEFAULT '',purchase_url text,package text NOT NULL CHECK(package IN('Basic','Standard','Premium')),amount integer NOT NULL,status text NOT NULL DEFAULT 'submitted' CHECK(status IN('submitted','corrections_requested','approved','rejected')),payment_status text NOT NULL DEFAULT 'pending' CHECK(payment_status IN('pending','verified','refunded')),admin_note text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.author_submissions TO authenticated; GRANT ALL ON public.author_submissions TO service_role;
ALTER TABLE public.author_submissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_submission_read ON public.author_submissions FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY own_submission_insert ON public.author_submissions FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND status='submitted' AND payment_status='pending' AND ((package='Basic' AND amount=150) OR (package='Standard' AND amount=275) OR (package='Premium' AND amount=395)));
CREATE POLICY admin_submissions ON public.author_submissions FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.community_settings (key text PRIMARY KEY,value jsonb NOT NULL DEFAULT '{}');
GRANT SELECT ON public.community_settings TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.community_settings TO authenticated; GRANT ALL ON public.community_settings TO service_role;
ALTER TABLE public.community_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_settings ON public.community_settings FOR SELECT USING(true); CREATE POLICY admin_settings ON public.community_settings FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,title text NOT NULL,body text NOT NULL DEFAULT '',read boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.notifications TO authenticated; GRANT ALL ON public.notifications TO service_role;
ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_notifications ON public.notifications FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE INDEX shelf_book_idx ON public.reader_shelves(book_id); CREATE INDEX contribution_book_idx ON public.contributions(book_id); CREATE INDEX contribution_parent_idx ON public.contributions(parent_id); CREATE INDEX rating_book_idx ON public.book_ratings(book_id); CREATE INDEX vote_book_idx ON public.good_book_votes(book_id);
CREATE VIEW public.book_engagement WITH (security_invoker=false) AS SELECT b.id AS book_id,(SELECT count(*) FROM public.reader_shelves s WHERE s.book_id=b.id AND s.category='Currently Reading') AS reading,(SELECT count(*) FROM public.reader_shelves s WHERE s.book_id=b.id AND s.category='Completed') AS completed,(SELECT count(DISTINCT s.user_id) FROM public.reader_shelves s WHERE s.book_id=b.id) AS participants,(SELECT count(*) FROM public.good_book_votes v WHERE v.book_id=b.id) AS votes,(SELECT coalesce(avg(r.rating),0) FROM public.book_ratings r WHERE r.book_id=b.id) AS rating,(SELECT count(*) FROM public.book_ratings r WHERE r.book_id=b.id) AS ratings,(SELECT count(*) FROM public.contributions c WHERE c.book_id=b.id AND c.source='reader' AND c.published) AS discussions,(SELECT count(*) FROM public.contribution_likes l JOIN public.contributions c ON c.id=l.contribution_id WHERE c.book_id=b.id AND c.source='reader' AND c.published) AS likes FROM public.books b WHERE b.published;
GRANT SELECT ON public.book_engagement TO anon,authenticated; GRANT ALL ON public.book_engagement TO service_role;